import csv, re
from collections import defaultdict, Counter
rows=list(csv.DictReader(open('captures/NEUTRALS-STAGING.tsv',encoding='utf-8'),delimiter='\t'))
print('staged cells:',len(rows))
def parse(r):
    s=r['source']
    m=re.search(r'series (.*?) \[(.*?)\] n=(\d+)-(\d+)',s)
    term,parent,n0,n1=(m.group(1),m.group(2),int(m.group(3)),int(m.group(4))) if m else ('','',0,0)
    return dict(Z=int(r['Z']),l=int(r['l']),mult=int(r['mult']),term=term.strip(),
                parent=parent.strip(),n0=n0,n1=n1,delta=float(r['delta']),
                spread=float(r['B']),tier=r['tier'],members=int(r['bound'].split()[0]),
                limit=r['bound'].split('limit ')[-1])
P=[parse(r) for r in rows]
AB=[p for p in P if p['tier'] in ('A','B')]
print('A/B cells:',len(AB))
K=defaultdict(list)
for p in AB: K[(p['Z'],p['l'],p['mult'])].append(p)
coll={k:v for k,v in K.items() if len(v)>1}
print('keys:',len(K),' colliding keys:',len(coll),' cells inside collisions:',sum(len(v) for v in coll.values()))
# what differs inside a collision?
diff=Counter()
for k,v in coll.items():
    parents={p['parent'] for p in v}; terms={p['term'] for p in v}; lims={p['limit'] for p in v}
    d=[]
    if len(parents)>1: d.append('parent')
    if len(terms)>1: d.append('term')
    if len(lims)>1: d.append('limit')
    if not d: d.append('NOTHING(identical labels)')
    diff['+'.join(d)]+=1
print('what separates the colliding cells:')
for k,v in diff.most_common(): print(f'   {k}: {v} keys')
# do parents alone resolve?
K2=defaultdict(list)
for p in AB: K2[(p['Z'],p['l'],p['mult'],p['parent'])].append(p)
print('\nkey + parent  -> keys:',len(K2),' still colliding:',sum(1 for v in K2.values() if len(v)>1))
K3=defaultdict(list)
for p in AB: K3[(p['Z'],p['l'],p['mult'],p['term'])].append(p)
print('key + term    -> keys:',len(K3),' still colliding:',sum(1 for v in K3.values() if len(v)>1))
K4=defaultdict(list)
for p in AB: K4[(p['Z'],p['l'],p['mult'],p['limit'])].append(p)
print('key + limit   -> keys:',len(K4),' still colliding:',sum(1 for v in K4.values() if len(v)>1))
